exchange_delivered_order_items:
order = self.db.orders.get(order_id)
if order is None:
    raise ValueError("Order not found")
if order.status != "delivered":
    raise ValueError("Non-delivered order cannot be exchanged")
all_ids = [it["item_id"] for it in order.items]
for item_id in item_ids:
    if item_ids.count(item_id) > all_ids.count(item_id):
        raise ValueError(f"Number of {item_id} not found.")
if len(item_ids) != len(new_item_ids):
    raise ValueError("The number of items to be exchanged should match")
diff = 0
for item_id, new_id in zip(item_ids, new_item_ids):
    item = next(it for it in order.items if it["item_id"] == item_id)
    pid = item["product_id"]
    variant = None
    product = self.db.products.get(pid)
    if product is not None:
        variant = (product.variants or {}).get(new_id)
    if variant is None:
        row = self.db.items.get(new_id)
        if row is not None and row.model_dump().get("product_id", pid) == pid:
            variant = {"available": row.available, "price": row.price, "options": row.options}
    if variant is None or not variant.get("available"):
        raise ValueError(f"New item {new_id} not found or available")
    diff += variant["price"] - item["price"]
diff = round(diff, 2)
user = self.db.users.get(order.user_id)
methods = (user.payment_methods or {}) if user else {}
if payment_method_id not in methods:
    raise ValueError("Payment method not found")
pm = methods[payment_method_id]
if pm.get("source") == "gift_card" and pm.get("balance", 0) < diff:
    raise ValueError("Insufficient gift card balance to pay for the price difference")
order.status = "exchange requested"
order.exchange_items = sorted(item_ids)
order.exchange_new_items = sorted(new_item_ids)
order.exchange_payment_method_id = payment_method_id
order.exchange_price_difference = diff
return order.model_dump()

